import {paperComparisonHTML,comparePaper} from './paper-data.js';
import {normalize,signature,descriptiveSessions,analyze,references,mean,ANALYSIS_VERSION} from './analysis.js';
import {db,studies,csv,download} from './core.js';
import {projectCode} from './project.js';
let imported=[],classData=[],chosen='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(x,d=2)=>typeof x==='number'&&Number.isFinite(x)?x.toFixed(d):'—';
const ptext=x=>typeof x==='number'&&Number.isFinite(x)?x<.001?'< .001':x.toFixed(3):'—';
const rows=sessions=>{const seen=new Map();for(const s of sessions)if(!seen.has(s.id))seen.set(s.id,s);return [...seen.values()];};
const safe=s=>{try{return normalize(s).sessions;}catch{return [];}};
function reportData(report){return {version:ANALYSIS_VERSION,created:new Date().toISOString(),key:report.key,selectedParticipants:report.sessions.map(s=>({id:s.id,participant:s.participant})),excluded:report.excluded,quality:report.quality,results:report.results,reference:references[report.key.split(' | ')[0]],paperComparison:comparePaper(report.descriptive||report.sessions,report.key.split(' | ')[0]),method:'每被试等权条件差值；配对 t（双侧）；95% CI 未作多重比较校正；Holm p 在本实验全部已计算检验中调整；n>=5 且各细分格至少10次；d_z=mean(diff)/SD(diff)；符号检验供敏感性分析。'};}
function conclusion(report){const rt=report.results.find(r=>['cue_rt','sector_rt','axis_rt'].includes(r.id)),acc=report.results.find(r=>['cue_acc','sector_acc','axis_acc'].includes(r.id));if(!rt||rt.pHolm===null)return '目前不足以判断改进效果。需先达到完整配对人数，并取得各条件的正确反应。';if(rt.pHolm<.05&&rt.mean<0){if(acc?.pHolm!==null&&acc?.pHolm<.05&&acc.mean<0)return '速度提高但正确率显著下降，存在速度—准确率权衡，不能判定整体改进。';return '反应时证据支持提速；同时报告正确率差与区间。正确率未显著下降不等于已证明准确率不受损。';}return rt.pHolm<.05?'反应时显著变慢，与提速预测相反。':'尚无足够证据支持提速；不等于证明改进没有效果。';}
export function analysisPage(app){
 const all=rows([...safe(db.read()),...imported]),keys=[...new Set(all.filter(s=>s.mode==='formal').map(signature))];
 if(!keys.includes(chosen))chosen=keys[0]||'';
 const report=chosen?analyze(all,chosen):null,experiment=chosen.split(' | ')[0],reference=references[experiment];if(report)report.descriptive=descriptiveSessions(all,chosen);
 app.innerHTML=`<section class="page-head"><div class="eyebrow">EVIDENCE DESK</div><h1>让发现，经得起比较。</h1><p>效应计算、原文数值对比与改进检验。先汇总每个人，再比较条件；试次数不会被当作被试人数。</p></section>
 <section class="panel"><h3>汇集真实记录</h3><p class="spaced">本机读取已完成记录；其他电脑请导出完整 JSON 后导入，也可读取项目 ${esc(projectCode())} 已上传记录。演示数据不会进入统计。</p><div class="result-actions"><label class="secondary">导入本组 JSON<input id="analysis-import" type="file" accept=".json,application/json" multiple class="analysis-file"></label><button class="secondary" id="analysis-fetch">读取课程项目记录</button><label class="secondary">导入全班参照 JSON<input id="class-import" type="file" accept=".json,application/json" multiple class="analysis-file"></label></div><p id="analysis-message" class="small spaced" role="status"></p><p class="small">本组导入 ${imported.length} 条，全班参照 ${classData.length} 条。本次导入仅保留在页面内存，刷新后需重新导入。不会覆盖原始记录，不上传导入文件。跨电脑须协调唯一匿名编号。</p></section>
 <section class="panel"><h3>按版本分开分析</h3><label class="field spaced">选择实验与版本<select id="analysis-group">${keys.length?keys.map(k=>`<option value="${esc(k)}" ${k===chosen?'selected':''}>${esc(studies[k.split(' | ')[0]].title+' | '+k)}</option>`).join(''):'<option value="">暂无摄像头采集记录</option>'}</select></label><p class="small">原文反应时对照可读取当前版本的低、中、高档摄像头记录，只作描述。正式效应检验仍仅纳入高档，且每个细分格有效任务至少 10 次。相同编号在同一版本只选最早完成的达标记录；中断不计，错误和超时仍计入正确率。不同协议、档位、采集政策不合并。眼动误差不作排除门槛。</p>${report?`<div class="stats-grid spaced"><div class="stat"><b>${report.sessions.length}</b><span>完整配对编号数（每实验 ≥5）</span></div><div class="stat"><b>${report.excluded.incomplete}</b><span>细分格不足 10 次的记录</span></div><div class="stat"><b>${report.excluded.duplicate}</b><span>重复编号记录已去重</span></div><div class="stat"><b>${report.total}</b><span>当前版本待核查记录数</span></div></div><p class="small">编号数不能自动证明真人身份或排除作者本人；正式提交前需人工核实确为老师要求的其他参与者。</p>`:'<div class="notice mint spaced">暂无可用于推断的记录。先用高档收集真实他人数据并导入；不会用体验记录生成显著结果。</div>'}</section>
 ${report?`<section class="panel"><h3>效应与改进检验</h3><p class="spaced">差值方向见每行名称。先算每人每细分格的均值，再等权合成条件差。正确 RT 排除错误、过早（&lt;150 ms）、超时及中断；同形斜率使用三个角度都有正确反应的被试。</p><div class="analysis-table"><table class="result-table"><thead><tr><th>比较</th><th>配对 n</th><th>平均差 / 斜率</th><th>95% CI</th><th>Cohen d<sub>z</sub></th><th>t(df)</th><th>原始 p</th><th>Holm p</th><th>判断</th></tr></thead><tbody>${report.results.map(r=>`<tr><td>${esc(r.label)}<br><small>${r.kind} · ${r.unit}</small></td><td>${r.n}</td><td>${number(r.mean)}</td><td>${r.ci?r.ci.map(x=>number(x)).join(' ～ '):'—'}</td><td>${number(r.dz)}</td><td>${r.t===null?'—':number(r.t)+' ('+r.df+')'}</td><td>${ptext(r.p)}</td><td>${ptext(r.pHolm)}</td><td>${esc(r.conclusion)}<br><small>${esc(r.status)}</small></td></tr>`).join('')}</tbody></table></div><div class="notice mint spaced">${conclusion(report)}</div><details class="spaced"><summary>统计方法、敏感性与缺失值</summary><p class="spaced">双侧配对 t / 对单人斜率的一样本 t；差值需近似正态，5 人仅为作业最低人数，不能保证功效。d<sub>z</sub> 使用被试间差值的标准差。95% CI 为未校正的均值差区间，不是 d 的区间；结论采用本实验所有可计算检验的 Holm 校正 p（α=.05）。零方差不输出虚假的无穷大效应或显著性。符号检验忽略大小、去掉零差值，仅作敏感性分析，未经多重校正。未显著不能解释为等效。</p>${report.results.map(r=>`<p>${esc(r.label)}：符号检验 n=${r.sign?.n??'—'}, p=${ptext(r.sign?.p)}；缺失指标 ${r.missing.length} 人${r.missing.length?'（'+r.missing.map(esc).join('、')+'）':''}。</p>`).join('')}<p><a href="https://www.itl.nist.gov/div898/handbook/prc/section3/prc311.htm" target="_blank" rel="noopener">NIST：配对分析公式 ↗</a></p></details></section>
 <p class="notice spaced">当前档位与版本：${esc(chosen)}。原文对照读取 ${report.descriptive.length} 个采集编号；短版不因此计入正式统计人数。</p>${paperComparisonHTML(report.descriptive,experiment)}
 <section class="panel"><h3>数据质量与人数核查</h3><div class="analysis-table"><table class="result-table"><thead><tr><th>匿名编号</th><th>最少细分格试次</th><th>验证误差 px</th><th>原型参考质量</th></tr></thead><tbody>${report.quality.map(q=>`<tr><td>${esc(q.participant)}</td><td>${q.minCell}</td><td>${number(q.error,0)}</td><td>${q.qualityPass===true?'参考线内':q.qualityPass===false?'参考线外（未排除）':'未提供'}</td></tr>`).join('')}</tbody></table></div><p class="small spaced">没有 AOI 样本者仅在眼动指标中缺失，不伪造为 0%。原型采样占比不等于专业注视时长；结合误差与热图解释。</p></section>
 <section class="panel"><h3>与全班数据比较</h3>${classPanel(report)}<p class="small spaced">只比较完全相同协议、档位和采集政策。全班样本可能包含本组，不作独立样本检验；此处为描述性并排对照。其他同学的不同实验格式需要先做方法一致性审核，不能直接混算。</p></section>
 <section class="panel"><h3>保存分析</h3><div class="result-actions"><button class="secondary" id="analysis-json">导出分析报告 JSON</button><button class="secondary" id="analysis-csv">导出效应表 CSV</button><button class="secondary" id="participant-csv">导出每人差值 CSV</button></div><p class="small spaced">同时保留原始完整 JSON；分析报告记录版本、纳入编号、排除计数和逐人差值，便于复核。</p></section>`:referenceCards()}
`;
 app.querySelector('#analysis-group').onchange=e=>{chosen=e.target.value;analysisPage(app);};
 function message(s){app.querySelector('#analysis-message').textContent=s;}
 async function files(event,cohort){const files=[...event.target.files];try{let count=0,notes=[];for(const f of files){if(f.size>30*1024*1024)throw Error('单个 JSON 超过 30 MB，请分被试导出。');const r=normalize(await f.text());count+=r.sessions.length;notes.push(...r.errors);if(cohort==='class')classData=rows([...classData,...r.sessions]);else imported=rows([...imported,...r.sessions]);}analysisPage(app);message(`已读取 ${count} 条记录。${notes.length?'另有 '+notes.length+' 条跳过：'+notes.slice(0,2).join('；'):''}`);}catch(e){message('导入失败：'+e.message);}}
 app.querySelector('#analysis-import').onchange=e=>files(e,'own');app.querySelector('#class-import').onchange=e=>files(e,'class');
 app.querySelector('#analysis-fetch').onclick=async e=>{const b=e.currentTarget;b.disabled=true;message('正在读取项目已提交记录…');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const res=await fetch('https://attention-lab-production.up.railway.app/api/hw2/data?project='+encodeURIComponent(projectCode()),{signal:controller.signal});if(!res.ok)throw Error('服务器 HTTP '+res.status);const data=await res.json();if(data.ok===false)throw Error(data.msg||'服务器拒绝读取');const result=normalize(data);imported=rows([...imported,...result.sessions]);analysisPage(app);message(`读取 ${result.sessions.length} 条，跳过 ${result.errors.length} 条。${result.sessions.length?'不同版本已分开，完整格不足者不作推断。':'当前项目暂无可用记录。'}`);}catch(err){message('未读取成功：'+(err.name==='AbortError'?'请求超时':err.message)+'。可从老师后台下载完整 JSON 后导入。');b.disabled=false;}finally{clearTimeout(timer);}};
 if(report){app.querySelector('#analysis-json').onclick=()=>download('starparcel-analysis.json',JSON.stringify({...reportData(report),classReference:classData.length?reportData(analyze(classData,chosen)):null},null,2));app.querySelector('#analysis-csv').onclick=()=>download('starparcel-effects.csv',csv(report.results.map(({observations,missing,sign,...r})=>({...r,ci_low:r.ci?.[0],ci_high:r.ci?.[1],ci:undefined,key:chosen,analysis_version:ANALYSIS_VERSION}))),'text/csv;charset=utf-8');app.querySelector('#participant-csv').onclick=()=>download('starparcel-participant-differences.csv',csv(report.results.flatMap(r=>r.observations.map(o=>({...o,comparison:r.id,unit:r.unit,key:chosen})))),'text/csv;charset=utf-8');}
}
function referenceCards(){return ['drive','map','rotate'].map(id=>paperComparisonHTML([],id)).join('');}
function classPanel(report){if(!classData.length)return '<p class="spaced">尚未导入真实全班参照数据，不显示虚构的班级均值。</p>';const other=analyze(classData,report.key);if(!other.sessions.length)return '<p class="spaced">参照文件没有相同版本的完整记录，暂不可比。</p>';return `<div class="analysis-table spaced"><table class="result-table"><thead><tr><th>指标</th><th>本组平均差（n）</th><th>全班参照平均差（n）</th><th>本组−参照</th></tr></thead><tbody>${report.results.map((r,i)=>{const c=other.results[i];return `<tr><td>${esc(r.label)}</td><td>${number(r.mean)} (${r.n})</td><td>${number(c.mean)} (${c.n})</td><td>${number(r.mean===null||c.mean===null?null:r.mean-c.mean)} ${r.unit}</td></tr>`;}).join('')}</tbody></table></div>`;}
